from __future__ import annotations

from typing import Any, Dict, Optional, TypedDict


class Message(TypedDict, total=False):
    """A message as returned by every send and message endpoint."""

    #: your ``clientMessageId`` (generated by the SDK when you do not pass one)
    id: str
    #: WhatsApp message id, once sent
    externalId: Optional[str]
    to: str
    type: str
    #: queued, scheduled, sent, delivered, read, failed, canceled
    status: str
    error: Optional[str]
    scheduledAt: Optional[str]
    sentAt: Optional[str]
    deliveredAt: Optional[str]
    readAt: Optional[str]
    editedAt: Optional[str]
    revokedAt: Optional[str]
    createdAt: str
    #: True when the same clientMessageId was already accepted (nothing was sent again)
    duplicate: bool
    #: set by delete: ``canceled`` (still queued) or ``revoked`` (deleted for everyone)
    action: str


class WebhookEvent(TypedDict, total=False):
    """Body of every webhook delivery."""

    event: str
    instanceId: str
    #: unix time in milliseconds
    timestamp: int
    sandbox: bool
    data: Dict[str, Any]
